import React from 'react';
import './AboutUs.css';

function AboutUs() {
  return (
    <div className="about-us-container">
      <h1 className="about-us-heading">Sobre nosotros</h1>
      <p className="about-us-description">
        Bienvenidos a Paradise Nursery, su fuente número uno de plantas para interiores. 
        Nos dedicamos a ofrecerles lo mejor de la vida vegetal, poniendo especial énfasis 
        en la calidad, la purificación del aire y el bajo mantenimiento.
      </p>
      <p className="about-us-content">
        Nuestro equipo de amantes de las plantas trabaja incansablemente para garantizar que cada planta aporte frescura y vitalidad a tu hogar u oficina. 
        ¡Explora nuestro catálogo y comienza hoy mismo tu viaje verde!
      </p>
    </div>
  );
}

export default AboutUs;
